function stock_status( $status, $product ) {
		if ( ! is_a( $product, 'WC_Product' ) ) { return $status; }
		$pid = $product->get_id();
		if ( ! self::taikoma( $pid ) ) { return $status; }
		$av = (int) Petshop_AV_Stock::qty( $pid );
		if ( $av > 0 ) { return 'instock'; }
		return $status;
	}

