function stock_qty( $qty, $product ) {
		if ( ! is_a( $product, 'WC_Product' ) ) { return $qty; }
		$pid = $product->get_id();
		if ( ! self::taikoma( $pid ) ) { return $qty; }
		$av = (int) Petshop_AV_Stock::qty( $pid );
		$tiek = (int) $qty;                                  // WC `_stock` = tiekėjo kiekis
		return $av + max( 0, $tiek );
	}
